SINA_SMART["physio-chemical"] = {"lecture":"physio-chemical","title":"Synapses and chemical communication","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physio-chemical:e0","text":"Neuron-to-neuron signalling is electrical → chemical → electrical.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"physio-chemical:s1","text":"Describe and explain: What the lecture asks you to do","topic":"What the lecture asks you to do","sec":1,"importance":"standard","highYield":"untested"},{"id":"physio-chemical:s2","text":"Describe and explain: Synapse structure","topic":"Synapse structure","sec":2,"importance":"standard","highYield":"untested"},{"id":"physio-chemical:e1","text":"Ca²⁺ entry through presynaptic voltage-gated channels triggers exocytosis.","topic":"Six events at the synapse","sec":3,"importance":"core","highYield":"untested"},{"id":"physio-chemical:e2","text":"Six events: AP, Ca²⁺ entry, release, receptor binding, ions enter, graded potential.","topic":"Six events at the synapse","sec":3,"importance":"core","highYield":"untested"},{"id":"physio-chemical:e3","text":"EPSP: positive ions in (Na⁺). IPSP: negative ions in (Cl⁻), hyperpolarizes.","topic":"EPSPs, IPSPs and summation","sec":4,"importance":"core","highYield":"untested"},{"id":"physio-chemical:e4","text":"Rest -70 mV, threshold -50 to -55 mV, PSP about ±10 mV: one EPSP is not enough.","topic":"EPSPs, IPSPs and summation","sec":4,"importance":"core","highYield":"untested"},{"id":"physio-chemical:e5","text":"Temporal summation: one neuron, rapid firing. Spatial: many neurons at once.","topic":"EPSPs, IPSPs and summation","sec":4,"importance":"core","highYield":"untested"},{"id":"physio-chemical:e6","text":"Glutamate main excitatory; GABA (and glycine) main inhibitory.","topic":"Neurotransmitters","sec":5,"importance":"core","highYield":"untested"},{"id":"physio-chemical:e7","text":"ACh: nicotinic excitatory at the NMJ; muscarinic inhibitory in the heart.","topic":"Neurotransmitters","sec":5,"importance":"core","highYield":"untested"},{"id":"physio-chemical:e8","text":"Direct (ionotropic) = fast; indirect (second messenger, cAMP) = slow, long-lasting.","topic":"Neurotransmitters","sec":5,"importance":"core","highYield":"untested"},{"id":"physio-chemical:e10","text":"SSRIs block serotonin reuptake; tetanus toxin blocks GABA release.","topic":"Ending the signal, drugs and disease","sec":6,"importance":"core","highYield":"untested"},{"id":"physio-chemical:e9","text":"Signal ends by reuptake, enzymes (AChE: acetate + choline) and diffusion.","topic":"Ending the signal, drugs and disease","sec":6,"importance":"core","highYield":"untested"},{"id":"physio-chemical:s7","text":"Describe and explain: Sensory receptors and transduction","topic":"Sensory receptors and transduction","sec":7,"importance":"standard","highYield":"untested"},{"id":"physio-chemical:e11","text":"Tonic receptors adapt slowly (proprioceptors); phasic adapt fast (touch, smell).","topic":"Adaptation, habituation and sensitization","sec":8,"importance":"core","highYield":"untested"},{"id":"physio-chemical:e12","text":"Sensitization: serotonin → cAMP → K⁺ channels blocked → longer AP → more release.","topic":"Adaptation, habituation and sensitization","sec":8,"importance":"core","highYield":"untested"},{"id":"physio-chemical:e13","text":"Pain and temperature cross in the cord; fine touch and vibration in the medulla.","topic":"Sensory pathways and discrimination","sec":9,"importance":"core","highYield":"untested"},{"id":"physio-chemical:s10","text":"Describe and explain: The special senses at a glance","topic":"The special senses at a glance","sec":10,"importance":"standard","highYield":"untested"}],"vmap":{},"mlevel":{"odhouy":"a","zsbms4":"a","ea4pwm":"a","sggzty":"a","1pz202o":"a","yajjsg":"a","1l3cbh1":"a","1if5p8r":"a","1po1jlj":"a","1r3fjxh":"a","1bt6gxd":"a","uwwapo":"a","1q3x0r5":"a","ofugga":"a","1344073":"a","1wcwivc":"a","1hdb4uk":"x","zva2mb":"x"},"mapCounts":{"verified":0,"auto":16,"ambiguous":0,"missing":2},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physio-chemical:e0":{"s":0,"u":["Neuron-to-neuron signalling is electrical → chemical → electrical.","Every neuron-to-neuron message is therefore electrical → chemical → electrical : an action potential in the presynaptic cell, a neurotransmitter crossing the cleft, and a graded (or action) potential in the postsynaptic cell.","Neurons talk in two languages."],"dp":[]},"physio-chemical:s1":{"s":1,"u":["Describe the structure of a synapse and how information crosses it.","Describe neurotransmitter release, including the role of calcium."],"dp":[]},"physio-chemical:s2":{"s":2,"u":["A synapse is a connection point between a neuron and another neuron, a muscle ( neuromuscular synapse), a gland ( neuroglandular synapse) or another cell.","Chemical versus electrical synapses (standard comparison): electrical synapses join cells through gap junctions , are almost instantaneous and can pass current both ways; chemical synapses are one-way , have a short synaptic delay , and can amplify, inhibit and be modulated, which is why most CNS synapses are chemical."],"dp":[{"h":"Electrical versus chemical synapses","t":"Electrical synapses link cells through gap junctions, so current flows straight from one cell to the next with almost no delay and in both directions. That suits cells that must fire together, such as cardiac muscle and some smooth muscle. Chemical synapses are slower (a fraction of a millisecond of synaptic delay) and one-way, but the transmitter step lets the signal be amplified, inhibited, summed and changed by drugs. That flexibility is why almost all CNS signalling, and all of pharmacology at the synapse, is chemical. Standard comparison, added to cover the lecture's learning objective."}]},"physio-chemical:e1":{"s":3,"u":["Ca²⁺ entry through presynaptic voltage-gated channels triggers exocytosis.","Ca²⁺ entry : voltage-gated Ca²⁺ channels open and Ca²⁺ enters the terminal.","Neurotransmitter release : Ca²⁺ triggers exocytosis of synaptic vesicles."],"dp":[]},"physio-chemical:e2":{"s":3,"u":["Six events: AP, Ca²⁺ entry, release, receptor binding, ions enter, graded potential.","Ions enter : receptor binding opens ion channels in the postsynaptic membrane.","Ca²⁺ entry : voltage-gated Ca²⁺ channels open and Ca²⁺ enters the terminal."],"dp":[]},"physio-chemical:e3":{"s":4,"u":["EPSP: positive ions in (Na⁺). IPSP: negative ions in (Cl⁻), hyperpolarizes.","Ions: EPSP = Positive ions in (e.g.","Na⁺); IPSP = Negative ions in (e.g."],"dp":[]},"physio-chemical:e4":{"s":4,"u":["Rest -70 mV, threshold -50 to -55 mV, PSP about ±10 mV: one EPSP is not enough.","Numbers to know: resting potential -70 mV , threshold -50 to -55 mV , each PSP about ±10 mV .","Effect: EPSP = Depolarizes, towards threshold; IPSP = Hyperpolarizes, away from threshold."],"dp":[{"h":"Why one EPSP is never enough","t":"The lecture's numbers make the point: a neuron rests at -70 mV, fires at about -50 to -55 mV, and a single PSP moves it by about 10 mV. A neuron is therefore a counter, not a relay. It adds the EPSPs and IPSPs arriving from thousands of synapses (convergence) at the axon hillock, and fires only when excitation wins. This is what lets the nervous system make decisions rather than just pass messages on. Source: the lecture's summation slides."}]},"physio-chemical:e5":{"s":4,"u":["Temporal summation: one neuron, rapid firing. Spatial: many neurons at once.","Spatial summation : several presynaptic neurons stimulate the postsynaptic cell at the same time at different locations.","Temporal summation : one presynaptic neuron fires repeatedly in quick succession at the same location, so its EPSPs stack up in time."],"dp":[]},"physio-chemical:e6":{"s":5,"u":["Glutamate main excitatory; GABA (and glycine) main inhibitory.","GABA: The main inhibitory transmitter in the brain (glycine is also inhibitory).","By function : excitatory (glutamate) or inhibitory (GABA, glycine)."],"dp":[]},"physio-chemical:e7":{"s":5,"u":["ACh: nicotinic excitatory at the NMJ; muscarinic inhibitory in the heart.","Some transmitters can be both , depending on the receptor: acetylcholine is excitatory at the neuromuscular junction ( nicotinic receptor) and inhibitory in cardiac muscle ( muscarinic receptor).","By function : excitatory (glutamate) or inhibitory (GABA, glycine)."],"dp":[]},"physio-chemical:e8":{"s":5,"u":["Direct (ionotropic) = fast; indirect (second messenger, cAMP) = slow, long-lasting.","Long-lasting, slow synapses .","Indirect (second messengers): G protein → adenylate cyclase → cAMP → enzyme activation, changes in permeability, gene expression."],"dp":[]},"physio-chemical:e10":{"s":6,"u":["SSRIs block serotonin reuptake; tetanus toxin blocks GABA release.","Lecture examples: SSRIs block serotonin reuptake, keeping serotonin longer in the synapse (depression).","Tetanus toxin prevents GABA release from inhibitory neurons, causing uncontrolled spasms and lockjaw (too much excitation)."],"dp":[]},"physio-chemical:e9":{"s":6,"u":["Signal ends by reuptake, enzymes (AChE: acetate + choline) and diffusion.","Acetylcholine: AChE splits ACh into acetate + choline ; choline is actively taken back into the terminal and ChAT (choline acetyltransferase) rebuilds ACh from choline + acetyl CoA .","Diffusion away from the cleft."],"dp":[]},"physio-chemical:s7":{"s":7,"u":["Perception is the conscious interpretation of the world, created by patterns of brain activity; it is limited by our receptor types (we do not sense magnetic fields or UV), our sensitivity (only certain sound frequencies) and central filtering (attention).","The cerebral cortex handles both sensation (awareness of the stimulus) and perception (its interpretation)."],"dp":[]},"physio-chemical:e11":{"s":8,"u":["Tonic receptors adapt slowly (proprioceptors); phasic adapt fast (touch, smell).","Examples: Tonic receptors = Proprioceptors , muscle stretch receptors; Phasic receptors = Touch (a ring or watch is soon not felt), temperature, smell.","Adaptation: Tonic receptors = Slow or none; Phasic receptors = Rapid."],"dp":[]},"physio-chemical:e12":{"s":8,"u":["Sensitization: serotonin → cAMP → K⁺ channels blocked → longer AP → more release.","Mechanism: serotonin → cAMP cascade → K⁺ channels blocked → presynaptic action potential prolonged → more Ca²⁺ enters → more transmitter released.","Sensitization : a strong or noxious stimulus increases responsiveness."],"dp":[{"h":"Sensitization and pain","t":"The sensitization mechanism in the lecture is the cellular basis of why a burned or bruised area hurts more on the next touch. Serotonin released after the injury blocks presynaptic K⁺ channels through cAMP, so each action potential lasts longer, lets in more Ca²⁺ and releases more transmitter. The same input now produces a bigger output. Source: the lecture's neuron sensitization slide."}]},"physio-chemical:e13":{"s":9,"u":["Pain and temperature cross in the cord; fine touch and vibration in the medulla.","Where they cross : pain, temperature and coarse touch cross in the spinal cord ; fine touch, vibration and proprioception cross in the medulla .","So a cord lesion on one side removes pain and temperature on the opposite side below it."],"dp":[]},"physio-chemical:s10":{"s":10,"u":["Smell: Receptors = Olfactory receptors in the olfactory epithelium; Pathway = Olfactory bulb, CN I, limbic system and hypothalamus, olfactory cortex.","Taste: Receptors = Gustatory receptors in taste buds; Pathway = CN VII, IX, X → medulla → thalamus → gustatory cortex."],"dp":[]}},"meta":{"odhouy":{"a":"relationship","vg":"physio-chemical:e0/relationship/1"},"zsbms4":{"a":"recall","vg":"physio-chemical:e1/recall/1"},"ea4pwm":{"a":"recall","vg":"physio-chemical:e0/recall/1"},"sggzty":{"a":"relationship","vg":"physio-chemical:e4/relationship/1"},"1pz202o":{"a":"recall","vg":"physio-chemical:e5/recall/1"},"yajjsg":{"a":"recall","vg":"physio-chemical:e6/recall/1"},"1l3cbh1":{"a":"recall","vg":"physio-chemical:e7/recall/1"},"1if5p8r":{"a":"recall","vg":"physio-chemical:e8/recall/1"},"1po1jlj":{"a":"recall","vg":"physio-chemical:e9/recall/1"},"1r3fjxh":{"a":"recall","vg":"physio-chemical:e10/recall/1"},"1bt6gxd":{"a":"recall","vg":"physio-chemical:e10/recall/2"},"uwwapo":{"a":"recall","vg":"physio-chemical:e11/recall/1"},"1q3x0r5":{"a":"recall","vg":"physio-chemical:e12/recall/1"},"ofugga":{"a":"recall","vg":"physio-chemical:e13/recall/1"},"1344073":{"a":"recall","vg":"physio-chemical:e12/recall/2"},"1wcwivc":{"a":"relationship","vg":"physio-chemical:e0/relationship/2"}},"explRev":"477fd09eb60c"};
